import{_ as s,o as a,c as d,a3 as i}from"./chunks/framework.D8G7yXPy.js";const k=JSON.parse('{"title":"发行版本与快速启动","description":"","frontmatter":{},"headers":[],"relativePath":"guide/distributions.md","filePath":"guide/distributions.md"}'),o={name:"guide/distributions.md"};function t(c,e,p,l,n,r){return a(),d("div",null,[...e[0]||(e[0]=[i(`<h1 id="发行版本与快速启动" tabindex="-1">发行版本与快速启动 <a class="header-anchor" href="#发行版本与快速启动" aria-label="Permalink to &quot;发行版本与快速启动&quot;">​</a></h1><p>同一套前端通过源码导出提供独立使用方式。Admin、文档和公共包之间保留明确依赖边界，Mock 与自有后端遵循同一套 API 契约。源码归档包含可编辑的工程文件，需要安装依赖并构建后运行。</p><h2 id="纯前端发行包" tabindex="-1">纯前端发行包 <a class="header-anchor" href="#纯前端发行包" aria-label="Permalink to &quot;纯前端发行包&quot;">​</a></h2><p>在仓库根目录执行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:frontend</span></span></code></pre></div><p>输出目录为 <code>dist/distributions/</code>，包含 <code>ray-template-frontend-&lt;version&gt;/</code> 和同名 <code>.tar.gz</code>。解压后进入源码目录，使用仓库指定的 Node.js 26.13.0 与 pnpm 12.16.1：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>默认打开 <code>/ray-template/</code>，通过 MSW 体验登录、用户管理、路由和其他示例。纯前端包保留 Admin、文档、10 个共享包及必要工具；不包含后端工作区、数据库驱动、Redis 客户端、服务端启动脚本或数据库配置。前端开发、构建和文档使用不需要 Docker。</p><p>接入自己的服务时配置 <code>VITE_API_BASE_URL</code>、<code>VITE_API_MOCK=false</code>，具体协议见<a href="./backend.html">服务端接入</a>。这些前端变量会进入浏览器产物，只能放公开配置。</p><h2 id="发行物追溯" tabindex="-1">发行物追溯 <a class="header-anchor" href="#发行物追溯" aria-label="Permalink to &quot;发行物追溯&quot;">​</a></h2><p>归档内的 <code>distribution.json</code> 记录：</p><ul><li>发行类型和版本。</li><li>来源 Git 提交及是否含未提交改动；没有 Git 信息时保留已知的来源信息。</li><li>实际包含的 workspace 清单和源码文件数量。</li><li>导出内容的 SHA-256 摘要。</li></ul><p>导出会按依赖图保留所需工作区、裁剪锁文件、移除不可用命令与专属说明，并排除 <code>.git</code>、<code>node_modules</code>、本地环境配置、凭据、构建结果和临时验证资料。<code>pnpm dist:check</code> 检查导出计划和依赖完整性；干净环境中的安装、构建、运行需要另行验证。</p><p>导出命令只生成本地源码目录和归档。</p><h2 id="全栈发行包" tabindex="-1">全栈发行包 <a class="header-anchor" href="#全栈发行包" aria-label="Permalink to &quot;全栈发行包&quot;">​</a></h2><p>在完整仓库运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist:fullstack</span></span></code></pre></div><p>同一目录会生成 <code>ray-template-fullstack-&lt;version&gt;/</code> 与同名 <code>.tar.gz</code>。它包含相同的前端源码以及 <code>apps/server</code>、数据库迁移、Redis 配置和启动工具。后端采用 NestJS 12.3.3、Prisma 7.10.1、PostgreSQL 18，Redis 客户端为 6.3.1；Compose 配置使用 Redis 8.2.11。具体锁定版本以发行包清单和锁文件为准。</p><h3 id="本地开发" tabindex="-1">本地开发 <a class="header-anchor" href="#本地开发" aria-label="Permalink to &quot;本地开发&quot;">​</a></h3><p>安装依赖并准备 Docker Compose，然后运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fullstack:setup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:full</span></span></code></pre></div><p><code>setup</code> 首次创建 <code>apps/server/.env.local</code>，生成数据库、Redis、管理员随机密码和 JWT 签名密钥，启动 PostgreSQL 与 Redis，执行迁移并初始化管理员。配置文件按私有文件创建；请在本机读取初始用户名和密码，勿提交、上传或放进前端变量。Mock 的 <code>123456</code> 只用于前端演示。</p><p>再次执行 <code>setup</code> 会复用配置、保留已有账号和数据库内容。<code>dev:full</code> 等待后端就绪后再启动前端，通过 Vite 将同源 <code>/api/</code> 请求代理给后端，并关闭 Mock。默认地址为 <code>http://127.0.0.1:9527/ray-template/</code>；可用 <code>ADMIN_DEV_PORT</code> 和 <code>PORT</code> 分别指定前端和后端端口。按 <code>Ctrl+C</code> 关闭开发进程；<code>pnpm fullstack:stop</code> 停止 Compose 服务并保留数据卷。</p><h3 id="使用已有数据库与-redis" tabindex="-1">使用已有数据库与 Redis <a class="header-anchor" href="#使用已有数据库与-redis" aria-label="Permalink to &quot;使用已有数据库与 Redis&quot;">​</a></h3><p>将 <code>DATABASE_URL</code> 和 <code>REDIS_URL</code> 放入当前进程的安全环境中，然后执行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fullstack:setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --external</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:full</span></span></code></pre></div><p><code>--external</code> 跳过 Docker 服务启动，仍执行迁移和初始化。已有 <code>apps/server/.env.local</code> 时保留该文件，进程环境优先。应使用为本项目准备的数据库；迁移和初始化会创建或更新本项目的数据结构。停止外部数据服务由其部署环境负责。</p><h3 id="创建真实登录账号" tabindex="-1">创建真实登录账号 <a class="header-anchor" href="#创建真实登录账号" aria-label="Permalink to &quot;创建真实登录账号&quot;">​</a></h3><p>在用户管理新增资料后，有 <code>users:credentials</code> 权限的管理员可以为该账号点击 <strong>设置密码</strong>。已登录用户可在头像菜单的 <strong>个人信息</strong> 页面修改自己的密码，需要输入当前密码。改密或重设会撤销该账号的所有会话。密码要求 12–128 个字符。</p><p>无法登录时，运维可通过安全环境提供 <code>CREDENTIAL_USERNAME</code> 与 <code>CREDENTIAL_PASSWORD</code>，再执行 <code>pnpm server:credential:set</code>。该命令适用于直接访问项目数据库的运维终端。重复执行 <code>setup</code> 不会创建改名前的账号，也不会重置密码。不要把密码写进命令行、终端记录或 AI 对话。</p><h3 id="服务与运行检查" tabindex="-1">服务与运行检查 <a class="header-anchor" href="#服务与运行检查" aria-label="Permalink to &quot;服务与运行检查&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令或接口</th><th>用途</th></tr></thead><tbody><tr><td><code>pnpm server:build</code></td><td>生成 Prisma Client 并构建独立服务端产物</td></tr><tr><td><code>pnpm server:start</code></td><td>从服务端构建产物启动</td></tr><tr><td><code>pnpm server:check</code></td><td>服务端类型、单元/平台测试和构建</td></tr><tr><td><code>pnpm server:test:integration</code></td><td>使用 <code>TEST_DATABASE_URL</code>、<code>TEST_REDIS_URL</code> 验证真实存储与 HTTP 行为</td></tr><tr><td><code>GET /api/health/live</code></td><td>进程存活检查</td></tr><tr><td><code>GET /api/health/ready</code></td><td>PostgreSQL 与 Redis 就绪检查</td></tr></tbody></table><p>全栈包含配置校验、接口授权、会话撤销、Redis 限流、安全响应头、CORS、请求 ID、脱敏日志和操作审计。Redis 不可用时管理接口返回 503，不切换到每进程的临时认证或限流数据。缓存只用于可重建的演示读取结果，权限和会话每次从数据库核验。</p><p>生产模式默认关闭演示接口，并从后端提供的运行菜单中移除演示页面。路由编辑器仍可维护完整配置。真实后端请求失败不会回退到 Mock。</p><h3 id="容器启动" tabindex="-1">容器启动 <a class="header-anchor" href="#容器启动" aria-label="Permalink to &quot;容器启动&quot;">​</a></h3><p>准备仓库指定的 Node.js 26.13.0，以及已启动的 Docker 和 Compose v2 插件（<code>docker compose version</code>、<code>docker info</code> 均应成功）。从解压后的全栈源码或完整仓库根目录运行：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/fullstack.mjs</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 使用 pnpm 时，也可以运行 pnpm fullstack:up</span></span></code></pre></div><p>此命令创建私有配置、构建 Admin 和 API、启动 PostgreSQL 与 Redis、执行迁移和初始化，等服务就绪后打印本机入口。宿主机无需预先安装前端依赖。默认入口为 <code>http://127.0.0.1:8080/ray-template/</code>，可通过 <code>APP_PORT</code> 改端口。使用 <code>node scripts/fullstack.mjs stop</code> 停止服务，数据卷保留。多个隔离实例要为每份配置指定不同的 <code>RAY_COMPOSE_PROJECT</code>、宿主机端口和 <code>APP_PROXY_NETWORK</code>。</p><p>Nginx 将同源 <code>/api/</code> 转发给后端。默认只在回环地址暴露宿主机端口，生产模式关闭演示（可用 <code>APP_DEMO_ENABLED=true</code> 显式开启）。外部 HTTPS 入口设置 <code>APP_ORIGINS</code> 为实际浏览器来源、<code>APP_SESSION_COOKIE_SECURE=true</code>，保留同源的 <code>/ray-template/</code> 和 <code>/api/</code>。示例 Nginx 会覆盖转发头；如再接外层反代，应在 Nginx 的 real IP 设置中只信任实际上一跳，并验证转发头无法伪造限流地址。代理网段冲突时，修改 <code>APP_PROXY_NETWORK</code>（例如 <code>172.30.68</code>）。容器连接外部数据库或 Redis 时，用正确编码的 <code>APP_DATABASE_URL</code>、<code>APP_REDIS_URL</code> 指定目标；已有服务的本机开发走 <code>setup --external</code>。</p><h3 id="给部署者和-ai-的验收清单" tabindex="-1">给部署者和 AI 的验收清单 <a class="header-anchor" href="#给部署者和-ai-的验收清单" aria-label="Permalink to &quot;给部署者和 AI 的验收清单&quot;">​</a></h3><ol><li>先确认发行物含 <code>apps/server</code>、<code>deploy/compose.yaml</code> 和 <code>scripts/fullstack.mjs</code>。默认选容器方式；需要热更新时走本地开发；已有 PostgreSQL、Redis 时用专用数据库和 Redis 前缀。端口占用就换 <code>APP_PORT</code>（容器）或 <code>PORT</code>、<code>ADMIN_DEV_PORT</code>（本机开发）；数据库和 Redis 映射分别用 <code>POSTGRES_PORT</code>、<code>REDIS_PORT</code>。</li><li>准备 PostgreSQL 迁移权限、Redis 连接以及服务端私有配置。部署副本共享同一个 <code>JWT_SECRET</code>（32 个随机字节的 base64url 编码），不同环境使用不同密钥。升级旧工作区可重跑 <code>setup</code> 或 <code>up</code> 补齐缺少的密钥；先备份 PostgreSQL，再应用迁移，旧令牌需重新登录。初始化配置中的密码只用于第一次建号。</li><li>验证 <code>GET /api/health/live</code>、<code>GET /api/health/ready</code> 均返回 200，匿名 <code>GET /api/admin/route-config</code> 返回 401。登录后检查用户管理、个人信息和路由管理；为测试账号设置密码，并确认只读账号不能调用写接口。空菜单账号仍应能打开个人信息。</li><li>如只有存活检查通过，用 Compose 的 <code>ps -a</code>、<code>logs initialize server</code> 检查迁移、初始化与连接。命令需使用 <code>--env-file apps/server/.env.local -f deploy/compose.yaml --profile app -p &lt;项目名&gt;</code>。只看脱敏日志，不回显环境文件。若浏览器登录后仍返回 401，检查实际访问源、同源代理和 Cookie 的 Secure 设置。对外部署还要验证目标环境的 HTTPS、备份恢复与代理限流。</li></ol><p><code>node deploy/smoke.mjs</code> 使用独立的临时 Compose 项目检查迁移、构建、登录、路由、CORS、演示开关和代理限流，并只清理它创建的测试资源。</p><h3 id="生成分支与-release-资产" tabindex="-1">生成分支与 Release 资产 <a class="header-anchor" href="#生成分支与-release-资产" aria-label="Permalink to &quot;生成分支与 Release 资产&quot;">​</a></h3><p>维护者在 GitHub Actions 从 <code>main</code> 手动运行 <strong>Source distributions</strong>。默认只验证并上传本次运行的归档。要更新生成的 <code>frontend</code> 分支，选择 <code>sync_frontend</code>；该分支从主线导出，不用于独立开发。要给已有 Release 附加两个源码包及 SHA-256 校验文件，另行填写 <code>release_tag</code>。工作流检查标签版本及提交、验证归档，并保留已上传的同名资产。</p>`,44)])])}const u=s(o,[["render",t]]);export{k as __pageData,u as default};
